MOTIF_NAME = 'knight_outpost_attacking_center'
MOTIF_DESCRIPTION = 'The side to move has a knight on a protected outpost square (immune to opponent pawns, defended by a friendly pawn) that attacks at least one central square (d4,e4,d5,e5), while the opponent has no such knight.'
def motif(fen: str) -> bool:
    import chess
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm

    central_squares = [chess.E4, chess.D4, chess.E5, chess.D5]

    def is_protected_outpost(sq, color):
        if board.piece_at(sq) is None:
            return False
        piece = board.piece_at(sq)
        if piece.piece_type != chess.KNIGHT or piece.color != color:
            return False
        # Not attackable by opponent pawns
        opp_pawn_attacks = board.pieces(chess.PAWN, not color)
        for psq in opp_pawn_attacks:
            attacks = board.attacks(psq)
            if sq in attacks:
                return False
        # Defended by a friendly pawn
        friendly_pawns = board.pieces(chess.PAWN, color)
        for psq in friendly_pawns:
            attacks = board.attacks(psq)
            if sq in attacks:
                return True
        return False

    def attacks_center(sq):
        kn_attacks = board.attacks(sq)
        for csq in central_squares:
            if csq in kn_attacks:
                return True
        return False

    stm_has = False
    for sq in board.pieces(chess.KNIGHT, stm):
        if is_protected_outpost(sq, stm) and attacks_center(sq):
            stm_has = True
            break

    if not stm_has:
        return False

    opp_has = False
    for sq in board.pieces(chess.KNIGHT, opp):
        if is_protected_outpost(sq, opp) and attacks_center(sq):
            opp_has = True
            break

    return not opp_has
